try { curl.exe -s -w "%{http_code} %{num_connects}\n" -o NUL -o NUL -o NUL http://127.0.0.1:8080/a.txt http://127.0.0.1:8080/b.txt http://127.0.0.1:8080/c.txt } finally { Stop-Process $server0 }
